-- AK Social database + security schema
create extension if not exists "uuid-ossp";
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, username text unique, display_name text, avatar_url text, bio text default '', role text default 'user' check(role in ('user','admin')), created_at timestamptz default now());
create table if not exists public.posts(id uuid primary key default uuid_generate_v4(), user_id uuid not null references public.profiles(id) on delete cascade, video_url text not null, caption text default '', trim_start numeric default 0, trim_end numeric, created_at timestamptz default now());
create table if not exists public.likes(user_id uuid references public.profiles(id) on delete cascade, post_id uuid references public.posts(id) on delete cascade, created_at timestamptz default now(), primary key(user_id,post_id));
create table if not exists public.comments(id uuid primary key default uuid_generate_v4(), user_id uuid references public.profiles(id) on delete cascade, post_id uuid references public.posts(id) on delete cascade, body text not null, created_at timestamptz default now());
create table if not exists public.follows(follower_id uuid references public.profiles(id) on delete cascade, following_id uuid references public.profiles(id) on delete cascade, created_at timestamptz default now(), primary key(follower_id,following_id), check(follower_id<>following_id));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name,avatar_url,username) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','New User'),new.raw_user_meta_data->>'avatar_url',lower(regexp_replace(coalesce(new.raw_user_meta_data->>'name','user')||'_'||substr(new.id::text,1,6),'[^a-zA-Z0-9_]','','g'))) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.posts enable row level security; alter table public.likes enable row level security; alter table public.comments enable row level security; alter table public.follows enable row level security;
create policy "profiles public read" on public.profiles for select using(true); create policy "profile self update" on public.profiles for update using(auth.uid()=id); create policy "posts public read" on public.posts for select using(true); create policy "posts own insert" on public.posts for insert with check(auth.uid()=user_id); create policy "posts own update" on public.posts for update using(auth.uid()=user_id); create policy "posts own delete" on public.posts for delete using(auth.uid()=user_id); create policy "likes read" on public.likes for select using(true); create policy "likes own" on public.likes for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "comments read" on public.comments for select using(true); create policy "comments own" on public.comments for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "follows read" on public.follows for select using(true); create policy "follows own" on public.follows for all using(auth.uid()=follower_id) with check(auth.uid()=follower_id);
insert into storage.buckets(id,name,public) values('videos','videos',true) on conflict(id) do nothing;
create policy "videos public read" on storage.objects for select using(bucket_id='videos'); create policy "videos auth upload" on storage.objects for insert to authenticated with check(bucket_id='videos' and (storage.foldername(name))[1]=auth.uid()::text); create policy "videos owner delete" on storage.objects for delete to authenticated using(bucket_id='videos' and owner_id=auth.uid()::text);
